--
-- Name: auto_sync_attendance_final(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_sync_attendance_final() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO public.attendance_final (
        date,
        emp_code,
        name,
        department,
        sub_department,
        status
    )
    SELECT 
        NEW.punch_date,
        NEW.user_id,
        NEW.name,
        em.department,
        em.sub_department,
        CASE 
            WHEN NEW.status = 1 THEN 'Present'
            ELSE 'Absent'
        END
    FROM emp_master em
    WHERE em.emp_code = NEW.user_id;

    RETURN NEW;
END;
$$;


--
-- Name: ensure_ct_log_partitions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_ct_log_partitions(months_ahead integer DEFAULT 3) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    i       int;
    start_d date;
    end_d   date;
    part    text;
BEGIN
    FOR i IN 0..months_ahead LOOP
        start_d := date_trunc('month', (CURRENT_DATE + (i || ' month')::interval))::date;
        end_d   := (start_d + interval '1 month')::date;
        part    := 'mes_submachine_ct_log_p' || to_char(start_d, 'YYYYMM');
        IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = part) THEN
            EXECUTE format(
                'CREATE TABLE %I PARTITION OF mes_submachine_ct_log FOR VALUES FROM (%L) TO (%L)',
                part, start_d, end_d);
        END IF;
    END LOOP;
END $$;


--
-- Name: fix_stroke_counts_sequence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fix_stroke_counts_sequence() RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE v bigint;
BEGIN
  SELECT setval(pg_get_serial_sequence('stroke_counts','id'),
                COALESCE((SELECT MAX(id) FROM stroke_counts),0)+1, false) INTO v;
  RETURN v;
END; $$;


--
-- Name: line_current_model(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.line_current_model() RETURNS TABLE(line_id integer, line_code text, line_name text, collector_status text, current_model_no integer, current_model text, current_mode text, shift_name text, last_update timestamp without time zone)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    r        record;
    v_num    int;
    v_name   text;
    v_map    text;
BEGIN
    FOR r IN
        SELECT ml.id AS l_id, ml.line_code AS l_code, ml.line_name AS l_name,
               ml.db_table_name AS l_tbl, ml.current_shift_row_id AS l_rowid,
               ml.collector_status AS l_coll
        FROM mes_lines ml WHERE ml.is_active = true ORDER BY ml.id
    LOOP
        line_id := r.l_id; line_code := r.l_code; line_name := r.l_name;
        collector_status := r.l_coll;
        current_model_no := NULL; current_model := NULL; current_mode := NULL;
        shift_name := NULL; last_update := NULL;
        v_num := NULL; v_name := NULL; v_map := NULL;

        IF r.l_tbl IS NOT NULL AND to_regclass(r.l_tbl) IS NOT NULL THEN
            BEGIN
                EXECUTE format(
                    'SELECT current_model_number, current_model_name, operating_status,
                            shift_name, timestamp
                       FROM %I
                      WHERE id = COALESCE($1, (SELECT id FROM %I
                                               WHERE is_shift_completed = false
                                               ORDER BY timestamp DESC NULLS LAST LIMIT 1))',
                    r.l_tbl, r.l_tbl)
                INTO v_num, v_name, current_mode, shift_name, last_update
                USING r.l_rowid;

                -- fuller configured name from the per-line model mapping (if set)
                SELECT mm.model_name INTO v_map
                FROM mes_model_mappings mm
                WHERE mm.line_id = r.l_id AND mm.model_number = v_num
                LIMIT 1;

                current_model_no := v_num;
                current_model := COALESCE(NULLIF(v_map,''), NULLIF(v_name,'Unknown'), v_name);
            EXCEPTION WHEN OTHERS THEN
                current_model := 'unavailable';
            END;
        ELSE
            current_model := 'not configured';
        END IF;

        RETURN NEXT;
    END LOOP;
END;
$_$;


--
-- Name: log_status_timeline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_status_timeline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    last_status TEXT;
    last_shift TEXT;
    last_date DATE;
    last_id INTEGER;
BEGIN

    -- Last open status
    SELECT id, status, shift_name, record_date
    INTO last_id, last_status, last_shift, last_date
    FROM ync_status_log
    WHERE end_time IS NULL
    ORDER BY id DESC
    LIMIT 1;

    -- Agar status, shift aur date same hai to kuch nahi karega
    IF last_status = NEW.operating_status
       AND last_shift = NEW.shift_name
       AND last_date = NEW.record_date THEN
        RETURN NEW;
    END IF;

    -- Previous log close karega
    IF last_id IS NOT NULL THEN
        UPDATE ync_status_log
        SET end_time = NOW(),
            duration_seconds = EXTRACT(EPOCH FROM (NOW() - start_time))
        WHERE id = last_id;
    END IF;

    -- New log create karega
    INSERT INTO ync_status_log (
        record_date,
        shift_name,
        status,
        start_time
    )
    VALUES (
        NEW.record_date,
        NEW.shift_name,
        NEW.operating_status,
        NOW()
    );

    RETURN NEW;

END;
$$;


--
-- Name: mes_ng_never_decrease(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mes_ng_never_decrease() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- explicit manual-reset bypass:  SET mes.allow_ng_reset='on'  before manual UPDATE
  IF current_setting('mes.allow_ng_reset', true) = 'on' THEN
     RETURN NEW;
  END IF;
  IF TG_OP='UPDATE'
     AND NEW.ng_count IS NOT NULL AND OLD.ng_count IS NOT NULL
     AND NEW.record_date IS NOT DISTINCT FROM OLD.record_date
     AND COALESCE(NEW.shift_name,'') = COALESCE(OLD.shift_name,'')
     AND NEW.ng_count < OLD.ng_count
  THEN
     NEW.ng_count := OLD.ng_count;   -- hold peak within the shift (mirrors OK GREATEST)
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_attendance_final(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_attendance_final() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Insert or update the attendance_final table
    INSERT INTO attendance_final (
        date,
        emp_code,
        emp_name,
        department,
        sub_department,
        status,
        role,
        uid,
        card,
        timestamp,
        punch,
        punch_date
    )
    SELECT
        NEW.timestamp::date AS date,
        em.emp_code,
        em.emp_name,
        em.department,
        em.sub_department,
        'Present' AS status, -- mark as present when punched
        em.role,
        NEW.uid,
        NEW.card,
        NEW.timestamp,
        NEW.punch,
        NEW.timestamp::date AS punch_date
    FROM emp_master em
    WHERE em.emp_code = NEW.emp_code -- match punch code with employee

    -- If a record for this employee and date already exists, update it
    ON CONFLICT (date, emp_code)
    DO UPDATE SET
        emp_name = EXCLUDED.emp_name,
        department = EXCLUDED.department,
        sub_department = EXCLUDED.sub_department,
        status = EXCLUDED.status,
        role = EXCLUDED.role,
        uid = EXCLUDED.uid,
        card = EXCLUDED.card,
        timestamp = EXCLUDED.timestamp,
        punch = EXCLUDED.punch,
        punch_date = EXCLUDED.punch_date;

    RETURN NEW;
END;
$$;


--
-- Name: sync_emp_master_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_emp_master_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE attendance_final
    SET
        name = NEW.emp_name,
        department = NEW.department,
        sub_department = NEW.sub_department
    WHERE emp_code = NEW.emp_code;

    RETURN NEW;
END;
$$;


--
-- Name: sync_insert_attendance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_insert_attendance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_name     TEXT;
    v_dept     TEXT;
    v_sub_dept TEXT;
    v_role     TEXT;
BEGIN
    SELECT emp_name, department, sub_department, role
    INTO   v_name, v_dept, v_sub_dept, v_role
    FROM   emp_master
    WHERE  emp_code = NEW.emp_code
    ORDER  BY id DESC
    LIMIT  1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    INSERT INTO attendance_final (
        date, emp_code, emp_name, department, sub_department,
        status, role, uid, card, timestamp, punch, punch_date
    )
    VALUES (
        NEW.timestamp::date,
        NEW.emp_code,
        v_name,
        v_dept,
        v_sub_dept,
        CASE
            WHEN NEW.punch = 0 THEN 'Absent'
            ELSE 'Present'
        END,
        v_role,
        NEW.uid,
        NEW.card,
        NEW.timestamp,
        NEW.punch,
        NEW.timestamp::date
    )
    ON CONFLICT (date, emp_code)
    DO UPDATE SET
        status     = EXCLUDED.status,
        timestamp  = EXCLUDED.timestamp,
        punch      = EXCLUDED.punch,
        punch_date = EXCLUDED.punch_date,
        uid        = EXCLUDED.uid,
        card       = EXCLUDED.card;

    RETURN NEW;
END;
$$;


--
-- Name: trg_insert_attendance_final(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_insert_attendance_final() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO attendance_final (
        date,
        emp_code,
        emp_name,
        department,
        sub_department,
        status,
        role,
        uid,
        card,
        timestamp,
        punch,
        punch_date
    )
    SELECT
        NEW.timestamp::date,
        em.emp_code,
        em.emp_name,
        em.department,
        em.sub_department,
        'Present',   -- always present on punch
        em.role,
        NEW.uid,
        NEW.card,
        NEW.timestamp,
        NEW.punch,
        NEW.timestamp::date
    FROM emp_master em
    WHERE em.emp_code = NEW.emp_code
    LIMIT 1   -- 🔥 IMPORTANT FIX

    ON CONFLICT (date, emp_code)
    DO UPDATE SET
        status = 'Present',
        timestamp = EXCLUDED.timestamp,
        punch = EXCLUDED.punch,
        punch_date = EXCLUDED.punch_date,
        uid = EXCLUDED.uid,
        card = EXCLUDED.card;

    RETURN NEW;
END;
$$;


